function handoffFindings(store, company, project) {
  const out = [];
  for (const h of store.handoffs(company.id, project.id).filter((x) => x.toModuleId === "internal-audit")) {
    const src = store.findRun(company.id, h.fromRunId, project.id);
    if (!src || src.status !== "archived") continue;
    if (src.moduleId === "icfr") {
      for (const d of src.result?.deficiencies || []) {
        if (d.grade === "improvement") continue;
        out.push({
          id: `B1:${d.id}`,
          title: d.description,
          severity: d.grade === "deficiency" ? "moderate" : "major",
          owner: d.owner,
          dueDate: d.dueDate,
          status: "open",
          closedDate: "",
          source: "handoff",
          fromModule: "B1",
          overdueDays: 0,
          tier: 0
        });
      }
    } else if (src.moduleId === "fraud") {
      for (const x of (src.result?.hits || []).filter((y4) => y4.level !== "info")) {
        out.push({
          id: `B5:${x.id}`,
          title: x.detail || x.refs.slice(0, 5).join(", "),
          severity: x.level === "high" ? "major" : "moderate",
          owner: "",
          dueDate: "",
          status: "open",
          closedDate: "",
          source: "handoff",
          fromModule: "B5",
          overdueDays: 0,
          tier: 0
        });
      }
    }
  }
  return out;
}

